import timetableJson from './timetable.json';

// Generated by scripts/kai-schedule-to-csv.mjs from the KAI Commuter timetable PDF (GAPEKA 2026).
// Re-run that script when the timetable changes; do not edit timetable.json by hand.

export type PilotStation = 'Manggarai' | 'Tebet' | 'Sudirman';
export type TrainLine = 'Bogor Line' | 'Cikarang Line';
export type DayType = 'weekday' | 'weekend';

export interface TimetableStop {
  /** Train number as printed, e.g. "1125", "1149F", "5505 - 5506". */
  train: string;
  /** Route as printed, e.g. "Dp - Jakk". */
  relasi: string;
  station: PilotStation;
  line: TrainLine;
  /** Same labels as supabase/seed/schedules.csv. */
  direction: string;
  days: DayType[];
  /** Departure in minutes from 00:00 of the service day; trains after midnight are > 1440. */
  minute: number;
  /** The stop just before this station; null when the train starts here. */
  prev: { code: string; name: string; minute: number } | null;
}

export interface Timetable {
  source: string;
  validFrom: string;
  stops: TimetableStop[];
}

export const TIMETABLE = timetableJson as Timetable;
